pub const DeferredPromise = struct {
    strong: jsc.JSPromise.Strong = .empty,
    route_bundle_indices: std.AutoArrayHashMapUnmanaged(RouteBundle.Index,void) = .{},

pub fn setRouteBundleState(self: *DeferredPromise, dev: *DevServer, state: RouteBundle.State) void {
            for (cp_iter_slice(self.route_bundle_indices.keys())) |route_bundle_index| {
                _ = &route_bundle_index;
                dev.routeBundlePtr(route_bundle_index).server_state = state;
            }
    }

pub fn reset(self: *DeferredPromise) void {
            _ = self.strong.deinit();
            _ = self.route_bundle_indices.clearRetainingCapacity();
    }

pub fn deinitIdempotently(self: *DeferredPromise) void {
            _ = self.strong.deinit();
            _ = self.route_bundle_indices.deinit(bun.default_allocator);
            self.route_bundle_indices = .{};
    }
};

pub const RequestEnsureRouteBundledCtx = struct {
    dev: *DevServer,
    req: ReqOrSaved,
    resp: AnyResponse,
    kind: DeferredRequest.Handler.Kind,
    route_bundle_index: RouteBundle.Index,

pub fn onDefer(self: *RequestEnsureRouteBundledCtx, bundle_field: BundleQueueType) bun.JSError!void {
            const requests_array: *DeferredRequest.List = (switch (bundle_field) {
.current_bundle => (&(self.dev.current_bundle).?.unwrap().requests),
.next_bundle => (&self.dev.next_bundle.requests),
});
            _ = try self.dev.deferRequest(requests_array, self.route_bundle_index, self.kind, self.req, self.resp);
    }

pub fn onLoaded(self: *RequestEnsureRouteBundledCtx) bun.JSError!void {
            switch (self.kind) {
.server_handler => {
_ = try self.dev.onFrameworkRequestWithBundle(self.route_bundle_index, (if ((self.req == .req)) .{ .stack = self.req.req } else .{ .saved = self.req.saved }), self.resp);
},
.bundled_html_page => {
_ = self.dev.onHtmlRequestWithBundle(self.route_bundle_index, self.resp, self.req.method());
},
}
    }

pub fn onFailure(self: *RequestEnsureRouteBundledCtx) bun.JSError!void {
            _ = try self.dev.sendSerializedFailures(.{ .http = self.resp }, (&self.dev.routeBundlePtr(self.route_bundle_index).data.framework.evaluate_failure.?)[0..1], .evaluation, null);
    }

pub fn onPluginError(self: *RequestEnsureRouteBundledCtx) bun.JSError!void {
            _ = self.resp.end("Plugin Error", false);
    }

pub fn toDevResponse(self: *RequestEnsureRouteBundledCtx) DevResponse {
            return .{ .http = self.resp };
    }
};

