pub const DeferredRequest = struct {
    route_bundle_index: RouteBundle.Index,
    handler: Handler,
    dev: *DevServer,
    referenced_by_devserver: bool = true,
    weakly_referenced_by_requestcontext: bool = false,

pub fn isAlive(self: *DeferredRequest) bool {
            return self.referenced_by_devserver;
    }

pub fn deref(self: *DeferredRequest) void {
            self.referenced_by_devserver = false;
            const should_free = (!self.weakly_referenced_by_requestcontext);
            _ = self.__deinit();
            if (should_free) {
                _ = self.__free();
            }
    }

pub fn weakRef(self: *DeferredRequest) void {
            _ = bun.assert((!self.weakly_referenced_by_requestcontext));
            self.weakly_referenced_by_requestcontext = true;
    }

pub fn weakDeref(self: *DeferredRequest) void {
            self.weakly_referenced_by_requestcontext = false;
            if ((!self.referenced_by_devserver)) {
                _ = self.__free();
            }
    }

pub fn onAbortWrapper(opaque_ptr: *anyopaque) void {
            const self: *DeferredRequest = @ptrCast(@alignCast(opaque_ptr));
            if ((!self.isAlive())) {
                return;
            }
            _ = self.onAbortImpl();
    }

pub fn onAbort(self: *DeferredRequest) void {
            _ = self.onAbortImpl();
    }

pub fn onAbortImpl(self: *DeferredRequest) void {
            _ = debugLog("DeferredRequest(0x{x}) onAbort", .{ @intFromPtr(self) });
            _ = self.abort();
            _ = assert((self.handler == .aborted));
    }

pub fn __free(self: *DeferredRequest) void {
            _ = self.dev.deferred_request_pool.put(@fieldParentPtr("data", self));
    }

pub fn __deinit(self: *DeferredRequest) void {
            _ = debugLog("DeferredRequest(0x{x}) deinitImpl", .{ @intFromPtr(self) });
            switch (self.handler) {
.server_handler => |*saved| {
_ = saved.deinit();
},
.bundled_html_page, .aborted => {

},
}
    }

pub fn abort(self: *DeferredRequest) void {
            _ = debugLog("DeferredRequest(0x{x}) abort", .{ @intFromPtr(self) });
            var handler = self.handler;
            _ = &handler;
            self.handler = .aborted;
            switch (handler) {
.server_handler => |*saved| {
_ = debugLog("  request url: {s}", .{ saved.request.url.byteSlice() });
            _ = saved.ctx.setSignalAborted(.ConnectionClosed);
            _ = saved.js_request.deinit();
},
.bundled_html_page => |r| {
_ = r.response.endWithoutBody(true);
},
.aborted => {

},
}
    }
    const max_preallocated = 16;
    pub const List = bun.deprecated.SinglyLinkedList(DeferredRequest);
    pub const Node = List.Node;
    const PromiseResponse = struct {
            promise: bun.jsc.JSPromise.Strong,
            global: *bun.jsc.JSGlobalObject,
        };
    const Handler = union(enum) {
            /// For a .framework route. This says to call and render the page.
            server_handler: bun.jsc.API.SavedRequest,
            /// For a .html route. Serve the bundled HTML page.
            bundled_html_page: ResponseAndMethod,
            /// Do nothing and free this node. To simplify lifetimes,
            /// the `DeferredRequest` is not freed upon abortion. Which
            /// is okay since most requests do not abort.
            aborted,
    
            /// Does not include `aborted` because branching on that value
            /// has no meaningful purpose, so it is excluded.
            const Kind = enum {
                server_handler,
                bundled_html_page,
            };
        };
};

pub const ResponseAndMethod = struct {
    response: AnyResponse,
    method: bun.http.Method,
};

