pub fn reset(self: *IncrementalResult) void {
            _ = self.framework_routes_affected.clearRetainingCapacity();
            _ = self.html_routes_soft_affected.clearRetainingCapacity();
            _ = self.html_routes_hard_affected.clearRetainingCapacity();
            _ = assert((self.failures_removed.items.len == 0));
            _ = self.failures_added.clearRetainingCapacity();
            _ = self.client_components_added.clearRetainingCapacity();
