pub const GraphTraceState = struct {
    client_bits: DynamicBitSetUnmanaged,
    server_bits: DynamicBitSetUnmanaged,

pub fn bits(self: *GraphTraceState, side: bake.Side) *DynamicBitSetUnmanaged {
            return (switch (side) {
.client => (&self.client_bits),
.server => (&self.server_bits),
});
    }

pub fn deinit(self: *GraphTraceState, alloc: Allocator) void {
            _ = self.client_bits.deinit(alloc);
            _ = self.server_bits.deinit(alloc);
    }

pub fn clear(self: *GraphTraceState) void {
            _ = self.server_bits.setAll(false);
            _ = self.client_bits.setAll(false);
    }

pub fn resize(self: *GraphTraceState, side: bake.Side, alloc: Allocator, new_size: usize) !void {
            const b = (switch (side) {
.client => (&self.client_bits),
.server => (&self.server_bits),
});
            if ((b.bit_length < new_size)) {
                _ = try b.resize(alloc, new_size, false);
            }
    }

pub fn clearAndFree(self: *GraphTraceState, alloc: Allocator) void {
            _ = ((self.client_bits.resize(alloc, 0, false)) catch unreachable);
            _ = ((self.server_bits.resize(alloc, 0, false)) catch unreachable);
    }
};

