pub const EntryPointList = struct {
    set: bun.StringArrayHashMapUnmanaged(Flags),

pub fn deinit(self: *EntryPointList, alloc: Allocator) void {
            _ = self.set.deinit(alloc);
    }

pub fn appendJs(self: *EntryPointList, alloc: Allocator, abs_path: []const u8, side: bake.Graph) !void {
            return self.append(alloc, abs_path, (switch (side) {
.server => .{ .server = true },
.client => .{ .client = true },
.ssr => .{ .ssr = true },
}));
    }

pub fn appendCss(self: *EntryPointList, alloc: Allocator, abs_path: []const u8) !void {
            return self.append(alloc, abs_path, .{ .client = true, .css = true });
    }

pub fn append(self: *EntryPointList, alloc: Allocator, abs_path: []const u8, flags: Flags) !void {
            var gop = try self.set.getOrPut(alloc, abs_path);
            _ = &gop;
            if (gop.found_existing) {
                const T = @typeInfo(Flags).@"struct".backing_integer.?;
                gop.value_ptr.* = @bitCast((@as(T, @bitCast(gop.value_ptr.*)) | @as(T, @bitCast(flags))));
            } else {
                gop.value_ptr.* = flags;
            }
    }
    pub const empty: EntryPointList = EntryPointList_empty;
    pub const Flags = packed struct(u8) {
            client: bool = false,
            server: bool = false,
            ssr: bool = false,
            /// When this is set, also set .client = true
            css: bool = false,
    
            unused: enum(u4) { unused = 0 } = .unused,
        };
};

pub const HTMLRouter = struct {
    map: Map,
    fallback: ?*HTMLBundle.HTMLBundleRoute,

pub fn get(self: HTMLRouter, path: []const u8) ?*HTMLBundle.HTMLBundleRoute {
            return ((self.map.get(path)) orelse (self.fallback));
    }

pub fn put(self: *HTMLRouter, alloc: Allocator, path: []const u8, route: *HTMLBundle.HTMLBundleRoute) !void {
            if (bun.strings.eqlComptime(path, "/*")) {
                self.fallback = route;
            } else {
                _ = try self.map.put(alloc, path, route);
            }
    }

pub fn clear(self: *HTMLRouter) void {
            _ = self.map.clearRetainingCapacity();
            self.fallback = null;
    }

pub fn deinit(self: *HTMLRouter, alloc: Allocator) void {
            _ = self.map.deinit(alloc);
    }
    pub const Map = bun.StringHashMapUnmanaged(*HTMLBundle.HTMLBundleRoute);
    pub const empty: HTMLRouter = HTMLRouter_empty;
};

pub const UnrefSourceMapRequest = struct {
    dev: *DevServer,
    body: uws.BodyReaderMixin(@This(),"body",runWithBody,finalize),

pub fn run(dev: *DevServer, _: *Request, resp: anytype) void {
            const ctx = bun.new(UnrefSourceMapRequest, .{ .dev = dev, .body = .init(dev.allocator()) });
            _ = ctx.dev.server.?.onPendingRequest();
            _ = ctx.body.readBody(resp);
    }

pub fn finalize(ctx: *UnrefSourceMapRequest) void {
            _ = ctx.dev.server.?.onStaticRequestComplete();
            _ = bun.destroy(ctx);
    }

pub fn runWithBody(ctx: *UnrefSourceMapRequest, body: []const u8, r: AnyResponse) !void {
            if ((body.len != 8)) {
                return error.InvalidRequest;
            }
            var generation: u32 = undefined;
            _ = &generation;
            _ = (blk_catch_2: { break :blk_catch_2 ((std.fmt.hexToBytes(std.mem.asBytes((&generation)), body)) catch |__ce_2| { _ = &__ce_2; return error.InvalidRequest; }); });
            const source_map_key = SourceMapStore.Key.init(cp_shl((if (comptime @typeInfo(@TypeOf(generation)) == .@"enum") cp_cast_int(u64, @intFromEnum(generation)) else cp_cast_int(u64, generation)), 32));
            _ = ctx.dev.source_maps.removeOrUpgradeWeakRef(source_map_key, .remove);
            _ = r.writeStatus("204 No Content");
            _ = r.end("", false);
    }
};

pub const TestingBatch = struct {
    entry_points: EntryPointList,

pub fn append(self: *TestingBatch, dev: *DevServer, entry_points: EntryPointList) !void {
            _ = assert((entry_points.set.count() > 0));
            const ep_keys = entry_points.set.keys();
            const ep_vals = entry_points.set.values();
            {
                var i: i32 = 0;
                _ = &i;
                const __end_1 = ep_keys.len;
                while (i < __end_1) : (i += 1) {
                    const k = ep_keys[@as(usize, @intCast(i))];
                    const v = ep_vals[@as(usize, @intCast(i))];
                    _ = try self.entry_points.append(dev.allocator(), k, v);
                }
            }
    }
    pub const empty: TestingBatch = TestingBatch_empty;
};

pub const PromiseEnsureRouteBundledCtx = struct {
    dev: *DevServer,
    global: *jsc.JSGlobalObject,
    promise: ?jsc.JSPromise.Strong = null,
    p: ?*jsc.JSPromise = null,
    already_loaded: bool = false,
    route_bundle_index: RouteBundle.Index,

pub fn ensurePromise(self: *PromiseEnsureRouteBundledCtx) jsc.JSPromise.Strong {
            if (self.promise) |p| {
                _ = &p;
                return p;
            }
            const strong = jsc.JSPromise.Strong.init(self.global);
            self.promise = strong;
            self.p = strong.get();
            return strong;
    }

pub fn onDefer(self: *PromiseEnsureRouteBundledCtx, bundle_field: BundleQueueType) bun.JSError!void {
            switch (bundle_field) {
.current_bundle => {
if (self.dev.current_bundle.?.promise.strong.hasValue()) {
                _ = bun.handleOom(self.dev.current_bundle.?.promise.route_bundle_indices.put(bun.default_allocator, self.route_bundle_index, .{}));
                self.p = self.dev.current_bundle.?.promise.strong.get();
                return;
            }
            const strong_promise = self.ensurePromise();
            _ = bun.handleOom(self.dev.current_bundle.?.promise.route_bundle_indices.put(bun.default_allocator, self.route_bundle_index, .{}));
            self.dev.current_bundle.?.promise.strong = strong_promise;
            return;
},
.next_bundle => {
if (self.dev.next_bundle.promise.strong.hasValue()) {
                _ = bun.handleOom(self.dev.next_bundle.promise.route_bundle_indices.put(bun.default_allocator, self.route_bundle_index, .{}));
                self.p = self.dev.next_bundle.promise.strong.get();
                return;
            }
            const strong_promise = self.ensurePromise();
            _ = bun.handleOom(self.dev.next_bundle.promise.route_bundle_indices.put(bun.default_allocator, self.route_bundle_index, .{}));
            self.dev.next_bundle.promise.strong = strong_promise;
            return;
},
}
    }

pub fn onLoaded(self: *PromiseEnsureRouteBundledCtx) bun.JSError!void {
            _ = self.ensurePromise();
            _ = try self.p.?.resolve(self.global, .true);
            _ = self.dev.vm.drainMicrotasks();
    }

pub fn onFailure(self: *PromiseEnsureRouteBundledCtx) bun.JSError!void {
            const promise_response = DeferredRequest.PromiseResponse{ .promise = self.ensurePromise(), .global = self.global };
            _ = try self.dev.sendSerializedFailures(DevResponse{ .promise = promise_response }, (&self.dev.routeBundlePtr(self.route_bundle_index).data.framework.evaluate_failure.?)[0..1], .evaluation, null);
    }

pub fn onPluginError(self: *PromiseEnsureRouteBundledCtx) bun.JSError!void {
            _ = self.ensurePromise();
            _ = try self.p.?.reject(self.global, bun.String.static("Plugin error").toJS(self.global));
            _ = self.dev.vm.drainMicrotasks();
    }

pub fn toDevResponse(self: *PromiseEnsureRouteBundledCtx) DevResponse {
            const promise_response = DeferredRequest.PromiseResponse{ .promise = self.ensurePromise(), .global = self.global };
            return .{ .promise = promise_response };
    }
};

pub const OptDir = ?std.fs.Dir;
pub const DumpDir = if (bun.FeatureFlags.bake_debugging_features) OptDir else void;

pub fn init(options: Options) bun.JSOOM!*DevServer {
        bun.analytics.Features.dev_server = (bun.analytics.Features.dev_server + 1);
        var dump_dir: ?std.fs.Dir = null;
        _ = &dump_dir;
        if (comptime bun.FeatureFlags.bake_debugging_features) {
            if (options.dump_sources) |dir| {
                _ = &dir;
                dump_dir = (blk_catch_3: { break :blk_catch_3 ((std.fs.cwd().makeOpenPath(dir, .{})) catch |e| { _ = &e; break :blk_catch_3 dir: {
                _ = bun.handleErrorReturnTrace(e, @errorReturnTrace());
                _ = Output.warn("Could not open directory for dumping sources: {}", .{ e });
                break :dir null;
}; }); });
            }
        }
        errdefer {
        if (bun.FeatureFlags.bake_debugging_features) {
            if (dump_dir) |*dir| {
                _ = &dir;
                _ = (dir.*).close();
            }
        }
        }
        var separate_ssr_graph = false;
        _ = &separate_ssr_graph;
        if (options.framework.server_components) |sc| {
            _ = &sc;
