        return try createDevServerFrameworkRequestArgsObject(dev.vm.global, args.router_type_main, args.route_modules, args.client_id, args.styles, args.params);
}

pub fn extractPathnameFromUrl(url: []const u8) []const u8 {
        var pathname = url;
        _ = &pathname;
        if (std.mem.indexOf(u8, url, "://")) |proto_end| {
            _ = &proto_end;
            pathname = url[(proto_end + 3)..];
        }
        if (std.mem.indexOfScalar(u8, pathname, 47)) |path_start| {
            _ = &path_start;
            const path_with_query = pathname[path_start..];
            const query_index = ((std.mem.indexOfScalar(u8, path_with_query, 63)) orelse (path_with_query.len));
            const hash_index = ((std.mem.indexOfScalar(u8, path_with_query, 35)) orelse (path_with_query.len));
            const end = @min(query_index, hash_index);
            pathname = path_with_query[0..end];
        }
        return pathname;
}
